// Spelling games for the chapter 2–3 word cards (117 recorded words):
//  - "Hear and pick": the right spelling among look-alikes (កាច / កាច់, ចត / ចទ …)
//  - "Build the word": tap the word's pieces in order.
// Look-alikes are generated by rules, so new words need no extra content.
// Pure functions only (no content import), so the game island stays small; the word lists
// come from content.ts → spellSets() and are passed in as props.
import type { Bi } from './content';

export interface SpellWord {
  id: string;        // review card id: "w:<key>"
  key: string;
  km: string;
  roman?: string;
  en?: string;
  audio: string;     // /assets/…
  set: string;       // "2-1" (chapter-lesson)
}
export interface SpellSet { id: string; chapter: number; lesson: number; title: Bi; words: SpellWord[] }

// ---- Khmer character classes ----
const COENG = '្';
const BANTOC = '់'; // ់
const isConsonant = (c: string) => c >= 'ក' && c <= 'អ';
const isIndependent = (c: string) => c >= 'ឣ' && c <= 'ឳ';
const isMark = (c: string) => c >= 'ា' && c <= '៑' || c === '៓' || c === '៝';

// Finals that sound the same (or nearly) at the end of a syllable: the classic spelling traps.
const SAME_FINAL: string[][] = [
  ['ក', 'គ', 'ខ'], ['ច', 'ជ'], ['ញ', 'ង'], ['ត', 'ទ', 'ធ', 'ដ'], ['ន', 'ណ'],
  ['ប', 'ព', 'ភ'], ['ម', 'ំ'], ['ល', 'ឡ'], ['ស', 'ះ'], ['យ', 'ី'],
];
// Vowels that are easy to confuse in writing.
const NEAR_VOWEL: string[][] = [['ិ', 'ី'], ['ុ', 'ូ'], ['េ', 'ែ'], ['ោ', 'ៅ'], ['ឹ', 'ឺ'], ['ៀ', 'ឿ'], ['ើ', 'ឿ'], ['ួ', 'ូ'], ['ា', 'ៅ']];
// Subscripts that are easy to confuse (same place in the mouth).
const NEAR_SUB: string[][] = [['ក', 'គ'], ['ច', 'ជ'], ['ត', 'ទ', 'ធ'], ['ប', 'ព', 'ភ'], ['ស', 'ហ']];

// First letters that pair up across the two series (same consonant, different vowel sound).
const SERIES_PAIR: string[][] = [['ក', 'គ'], ['ខ', 'ឃ'], ['ច', 'ជ'], ['ឆ', 'ឈ'], ['ដ', 'ឌ'], ['ត', 'ទ'], ['ថ', 'ធ'], ['ប', 'ព'], ['ផ', 'ភ'], ['ណ', 'ន'], ['ឡ', 'ល']];

const others = (groups: string[][], c: string) => [...new Set(groups.filter((g) => g.includes(c)).flat())].filter((x) => x !== c);

/** Index of the final consonant of the word (last consonant that is not a subscript), or -1. */
function finalIndex(chars: string[]): number {
  for (let i = chars.length - 1; i >= 0; i--) {
    if (isConsonant(chars[i]) && chars[i - 1] !== COENG) {
      // Only a final if nothing but ់ follows it.
      const after = chars.slice(i + 1).join('');
      return after === '' || after === BANTOC ? i : -1;
    }
  }
  return -1;
}

/** Plausible misspellings of a word, most instructive first. Never includes the word itself. */
export function lookAlikes(word: string): string[] {
  const chars = [...word];
  const out: string[] = [];
  const push = (s: string) => { if (s !== word && !out.includes(s)) out.push(s); };

  // 1. With or without ់ (the lesson's main point: កាច / កាច់).
  if (chars.at(-1) === BANTOC) push(chars.slice(0, -1).join(''));
  else if (isConsonant(chars.at(-1)!)) push(word + BANTOC);

  // 2. A final consonant that sounds the same.
  const f = finalIndex(chars);
  if (f > 0) {
    for (const alt of others(SAME_FINAL, chars[f])) {
      const c = [...chars];
      c[f] = alt;
      if (!isConsonant(alt)) c.splice(f + 1); // ំ / ះ / ី replace the whole ending
      push(c.join(''));
    }
  }
  // 3. A near vowel.
  chars.forEach((ch, i) => {
    for (const alt of others(NEAR_VOWEL, ch)) push(chars.map((x, j) => (j === i ? alt : x)).join(''));
  });
  // 4. A near subscript.
  chars.forEach((ch, i) => {
    if (chars[i - 1] !== COENG) return;
    for (const alt of others(NEAR_SUB, ch)) push(chars.map((x, j) => (j === i ? alt : x)).join(''));
  });
  // 5. The first letter from the other series (កាច / គាច).
  if (isConsonant(chars[0]) && chars[1] !== COENG) {
    for (const alt of others(SERIES_PAIR, chars[0])) push(alt + chars.slice(1).join(''));
  }
  return out;
}

const shuffle = <X,>(a: X[]) => a.map((v) => [Math.random(), v] as const).sort((x, y) => x[0] - y[0]).map((x) => x[1]);

/** The right spelling plus up to 3 look-alikes, shuffled. Falls back to other words of the same set. */
export function spellingChoices(w: SpellWord, pool: SpellWord[]): string[] {
  const looks = lookAlikes(w.km);
  // Keep ់-toggle first (when present), then a random mix of the rest.
  const first = looks.slice(0, 1);
  const picked = [...first, ...shuffle(looks.slice(1))].slice(0, 3);
  if (picked.length < 3) {
    const fill = shuffle(pool.filter((p) => p.set === w.set && p.km !== w.km && !picked.includes(p.km))).map((p) => p.km);
    picked.push(...fill.slice(0, 3 - picked.length));
  }
  return shuffle([w.km, ...picked]);
}

/**
 * Splits a word into the pieces a learner types or writes, in order:
 * a consonant (or independent vowel), a subscript (្ + consonant), each vowel or sign.
 */
export function pieces(word: string): string[] {
  const chars = [...word.replace(/[​-‍]/g, '')];
  const out: string[] = [];
  for (let i = 0; i < chars.length; i++) {
    const c = chars[i];
    if (c === COENG && chars[i + 1]) { out.push(COENG + chars[i + 1]); i++; }
    else out.push(c);
  }
  return out;
}

/** How a piece is shown on a tile: marks and subscripts sit on a dotted circle. */
export const tileLabel = (p: string) => (isConsonant(p[0]) || isIndependent(p[0]) ? p : `◌${p}`);
export const isMarkPiece = (p: string) => p.startsWith(COENG) || isMark(p);

/** Tiles for "Build the word": the word's pieces plus two decoys, shuffled. */
export function buildTiles(w: SpellWord): string[] {
  const parts = pieces(w.km);
  const decoys = new Set<string>();
  const f = finalIndex([...w.km]);
  if (!w.km.endsWith(BANTOC)) decoys.add(BANTOC);
  if (f > 0) others(SAME_FINAL, [...w.km][f]).forEach((d) => decoys.add(d));
  for (const p of parts) others(NEAR_VOWEL, p).forEach((d) => decoys.add(d));
  const extra = shuffle([...decoys].filter((d) => !parts.includes(d))).slice(0, 2);
  return shuffle([...parts, ...extra]);
}
